import consola from "consola"

import { refreshCopilotToken } from "~/lib/token"

import { copilotHeaders } from "./api-config"
import { state } from "./state"

type CopilotRequestInit = Omit<RequestInit, "headers"> & {
  headers?: Record<string, string>
}

interface CopilotFetchOptions {
  vision?: boolean
  refresh?: () => Promise<unknown>
}

function mergeHeaders(
  defaults: Record<string, string>,
  overrides?: Record<string, string>,
): Record<string, string> {
  return { ...defaults, ...overrides }
}

export async function copilotFetch(
  input: string | URL,
  init: CopilotRequestInit = {},
  options: CopilotFetchOptions = {},
): Promise<Response> {
  const send = () =>
    fetch(input, {
      ...init,
      headers: mergeHeaders(
        copilotHeaders(state, options.vision),
        init.headers,
      ),
    })

  const requestToken = state.copilotToken
  let response = await send()
  if (response.status !== 401 || init.signal?.aborted) return response
  if (init.body && typeof init.body !== "string") return response

  consola.warn(
    "Copilot request returned 401; refreshing IDE token and retrying",
  )
  try {
    await response.body?.cancel()
  } catch (error) {
    consola.debug("Failed to cancel rejected Copilot response body", error)
  }
  if (!requestToken || state.copilotToken === requestToken) {
    await (options.refresh ?? refreshCopilotToken)()
  }
  response = await send()
  return response
}

import consola from "consola"
import fs from "node:fs/promises"

import { PATHS } from "~/lib/paths"
import {
  getCopilotToken,
  type GetCopilotTokenResponse,
} from "~/services/github/get-copilot-token"
import { getDeviceCode } from "~/services/github/get-device-code"
import { getGitHubUser } from "~/services/github/get-user"
import { pollAccessToken } from "~/services/github/poll-access-token"

import { HTTPError } from "./error"
import { state } from "./state"

const readGithubToken = () => fs.readFile(PATHS.GITHUB_TOKEN_PATH, "utf8")

const writeGithubToken = (token: string) =>
  fs.writeFile(PATHS.GITHUB_TOKEN_PATH, token)

const REFRESH_LEEWAY_SECONDS = 60
const REFRESH_RETRY_SECONDS = 30

let refreshPromise: Promise<GetCopilotTokenResponse> | undefined
let refreshTimer: ReturnType<typeof setTimeout> | undefined
let shutdownHandlersInstalled = false
let shuttingDown = false

function scheduleTimer(callback: () => void, delaySeconds: number): void {
  if (shuttingDown) return
  if (refreshTimer) clearTimeout(refreshTimer)
  refreshTimer = setTimeout(callback, delaySeconds * 1000)
}

function scheduleRetry(): void {
  scheduleTimer(() => {
    void refreshCopilotToken().catch((error: unknown) => {
      consola.error("Copilot token refresh retry failed; retrying soon:", error)
      scheduleRetry()
    })
  }, REFRESH_RETRY_SECONDS)
}

function scheduleRefresh(response: GetCopilotTokenResponse): void {
  const delaySeconds = Math.max(
    1,
    Math.min(
      response.refresh_in - REFRESH_LEEWAY_SECONDS,
      response.expires_at
        - Math.floor(Date.now() / 1000)
        - REFRESH_LEEWAY_SECONDS,
    ),
  )
  scheduleTimer(() => {
    void refreshCopilotToken().catch((error: unknown) => {
      consola.error("Failed to refresh Copilot token; retrying soon:", error)
      scheduleRetry()
    })
  }, delaySeconds)
}

export function refreshCopilotToken(): Promise<GetCopilotTokenResponse> {
  refreshPromise ??= getCopilotToken()
    .then((response) => {
      state.copilotToken = response.token
      scheduleRefresh(response)
      consola.debug("Copilot token refreshed")
      if (state.showToken)
        consola.info("Refreshed Copilot token:", response.token)
      return response
    })
    .finally(() => {
      refreshPromise = undefined
    })
  return refreshPromise
}

export const setupCopilotToken = async () => {
  await refreshCopilotToken()
  consola.debug("GitHub Copilot Token fetched successfully!")

  if (!shutdownHandlersInstalled) {
    shutdownHandlersInstalled = true
    for (const sig of ["SIGINT", "SIGTERM"] as const) {
      process.once(sig, () => {
        shuttingDown = true
        if (refreshTimer) clearTimeout(refreshTimer)
      })
    }
  }
}

interface SetupGitHubTokenOptions {
  force?: boolean
}

export async function setupGitHubToken(
  options?: SetupGitHubTokenOptions,
): Promise<void> {
  try {
    const githubToken = await readGithubToken()

    if (githubToken && !options?.force) {
      state.githubToken = githubToken
      if (state.showToken) {
        consola.info("GitHub token:", githubToken)
      }
      await logUser()

      return
    }

    consola.info("Not logged in, getting new access token")
    const response = await getDeviceCode()
    consola.debug("Device code response:", response)

    consola.info(
      `Please enter the code "${response.user_code}" in ${response.verification_uri}`,
    )

    const token = await pollAccessToken(response)
    await writeGithubToken(token)
    state.githubToken = token

    if (state.showToken) {
      consola.info("GitHub token:", token)
    }
    await logUser()
  } catch (error) {
    if (error instanceof HTTPError) {
      consola.error("Failed to get GitHub token:", await error.response.json())
      throw error
    }

    consola.error("Failed to get GitHub token:", error)
    throw error
  }
}

async function logUser() {
  const user = await getGitHubUser()
  consola.info(`Logged in as ${user.login}`)
}

import consola from "consola"
import { events } from "fetch-event-stream"

import type { RequestedEffort } from "~/lib/effort"

import { copilotBaseUrl } from "~/lib/api-config"
import { copilotFetch } from "~/lib/copilot-fetch"
import { HTTPError } from "~/lib/error"
import { state } from "~/lib/state"

export const createChatCompletions = async (
  payload: ChatCompletionsPayload,
  signal?: AbortSignal,
) => {
  if (!state.copilotToken) throw new Error("Copilot token not found")

  const enableVision = payload.messages.some(
    (x) =>
      typeof x.content !== "string"
      && x.content?.some((x) => x.type === "image_url"),
  )

  // Agent/user check for X-Initiator header
  // Determine if any message is from an agent ("assistant" or "tool")
  const isAgentCall = payload.messages.some((msg) =>
    ["assistant", "tool"].includes(msg.role),
  )

  // Build headers and add X-Initiator
  const response = await copilotFetch(
    `${copilotBaseUrl(state)}/chat/completions`,
    {
      method: "POST",
      headers: { "X-Initiator": isAgentCall ? "agent" : "user" },
      body: JSON.stringify(payload),
      signal,
    },
    { vision: enableVision },
  )

  if (!response.ok) {
    consola.error("Failed to create chat completions", response)
    throw new HTTPError("Failed to create chat completions", response)
  }

  if (payload.stream) {
    return events(response)
  }

  return (await response.json()) as ChatCompletionResponse
}

// Streaming types

export interface ChatCompletionChunk {
  id: string
  object: "chat.completion.chunk"
  created: number
  model: string
  choices: Array<Choice>
  system_fingerprint?: string
  usage?: {
    prompt_tokens: number
    completion_tokens: number
    total_tokens: number
    prompt_tokens_details?: {
      cached_tokens: number
    }
    completion_tokens_details?: {
      accepted_prediction_tokens: number
      rejected_prediction_tokens: number
    }
  }
  error?: {
    type: string
    message: string
    code?: string
  }
}

interface Delta {
  content?: string | null
  role?: "user" | "assistant" | "system" | "tool"
  tool_calls?: Array<{
    index: number
    id?: string
    type?: "function"
    function?: {
      name?: string
      arguments?: string
    }
  }>
}

interface Choice {
  index: number
  delta: Delta
  finish_reason: "stop" | "length" | "tool_calls" | "content_filter" | null
  logprobs: object | null
}

// Non-streaming types

export interface ChatCompletionResponse {
  id: string
  object: "chat.completion"
  created: number
  model: string
  choices: Array<ChoiceNonStreaming>
  system_fingerprint?: string
  usage?: {
    prompt_tokens: number
    completion_tokens: number
    total_tokens: number
    prompt_tokens_details?: {
      cached_tokens: number
    }
  }
}

interface ResponseMessage {
  role: "assistant"
  content: string | null
  reasoning_text?: string | null
  tool_calls?: Array<ToolCall>
}

interface ChoiceNonStreaming {
  index: number
  message: ResponseMessage
  logprobs: object | null
  finish_reason: "stop" | "length" | "tool_calls" | "content_filter"
}

// Payload types

export interface ChatCompletionsPayload {
  messages: Array<Message>
  model: string
  temperature?: number | null
  top_p?: number | null
  max_tokens?: number | null
  stop?: string | Array<string> | null
  n?: number | null
  stream?: boolean | null

  frequency_penalty?: number | null
  presence_penalty?: number | null
  logit_bias?: Record<string, number> | null
  logprobs?: boolean | null
  response_format?: { type: "json_object" } | null
  seed?: number | null
  reasoning_effort?: RequestedEffort
  tools?: Array<Tool> | null
  tool_choice?:
    | "none"
    | "auto"
    | "required"
    | { type: "function"; function: { name: string } }
    | null
  user?: string | null
}

export interface Tool {
  type: "function"
  function: {
    name: string
    description?: string
    parameters: Record<string, unknown>
  }
}

export interface Message {
  role: "user" | "assistant" | "system" | "tool" | "developer"
  content: string | Array<ContentPart> | null

  name?: string
  tool_calls?: Array<ToolCall>
  tool_call_id?: string
}

export interface ToolCall {
  id: string
  type: "function"
  function: {
    name: string
    arguments: string
  }
}

export type ContentPart = TextPart | ImagePart | AudioPart

export interface TextPart {
  type: "text"
  text: string
}

export interface ImagePart {
  type: "image_url"
  image_url: {
    url: string
    detail?: "low" | "high" | "auto"
  }
}

export interface AudioPart {
  type: "input_audio"
  input_audio: {
    data: string
    format: "wav" | "mp3"
  }
}

import { copilotBaseUrl } from "~/lib/api-config"
import { copilotFetch } from "~/lib/copilot-fetch"
import { HTTPError } from "~/lib/error"
import { state } from "~/lib/state"

export const createEmbeddings = async (payload: EmbeddingRequest) => {
  if (!state.copilotToken) throw new Error("Copilot token not found")

  const response = await copilotFetch(`${copilotBaseUrl(state)}/embeddings`, {
    method: "POST",
    body: JSON.stringify(payload),
  })

  if (!response.ok) throw new HTTPError("Failed to create embeddings", response)

  return (await response.json()) as EmbeddingResponse
}

export interface EmbeddingRequest {
  input: string | Array<string>
  model: string
}

export interface Embedding {
  object: string
  embedding: Array<number>
  index: number
}

export interface EmbeddingResponse {
  object: string
  data: Array<Embedding>
  model: string
  usage: {
    prompt_tokens: number
    total_tokens: number
  }
}

import consola from "consola"
import { events } from "fetch-event-stream"
import { randomUUID } from "node:crypto"

import { copilotBaseUrl } from "~/lib/api-config"
import { copilotFetch } from "~/lib/copilot-fetch"
import { badRequest, HTTPError } from "~/lib/error"
import { state } from "~/lib/state"

import type {
  ChatCompletionChunk,
  ChatCompletionResponse,
  ChatCompletionsPayload,
  ToolCall,
} from "./create-chat-completions"

// ── Request translation: OpenAI Chat Completions → Responses API ──

interface ResponsesPayload {
  model: string
  input: Array<ResponsesInput>
  max_output_tokens?: number
  tools?: Array<ResponsesTool>
  tool_choice?: string | { type: string; name?: string }
  stream?: boolean
  reasoning?: { effort: string }
}

type ResponsesInput =
  | {
      type: "message"
      role: "developer" | "user" | "assistant"
      content: string | Array<ResponsesContentPart>
    }
  | { type: "function_call"; name: string; arguments: string; call_id: string }
  | { type: "function_call_output"; call_id: string; output: string }

interface ResponsesContentPart {
  type: "input_text" | "input_image" | "input_audio"
  text?: string
  image_url?: string
  detail?: string
  input_audio?: { data: string; format: string }
}

interface ResponsesTool {
  type: "function"
  name: string
  description?: string
  parameters: Record<string, unknown>
}

interface RawContentPart {
  type: string
  text?: string
  image_url?: { url?: string; detail?: string }
  input_audio?: { data?: string; format?: string }
}

export function translateMessageContent(
  content: string | Array<RawContentPart> | undefined,
): string | Array<ResponsesContentPart> {
  if (typeof content === "string") return content
  if (!content) return ""

  const parts: Array<ResponsesContentPart> = []
  for (const p of content) {
    if (p.type === "text") {
      parts.push({ type: "input_text", text: p.text ?? "" })
      continue
    }

    if (p.type === "image_url") {
      const url = p.image_url?.url
      if (!url) {
        consola.warn("Dropping image_url part with no url", {
          reason: "missing image_url.url",
        })
        continue
      }
      parts.push({
        type: "input_image",
        image_url: url,
        detail: p.image_url?.detail,
      })
      continue
    }

    if (p.type === "input_audio") {
      const data = p.input_audio?.data
      const format = p.input_audio?.format
      if (!data || !format) {
        consola.warn("Dropping input_audio part missing data or format", {
          hasData: Boolean(data),
          hasFormat: Boolean(format),
        })
        continue
      }
      parts.push({
        type: "input_audio",
        input_audio: { data, format },
      } as ResponsesContentPart)
      continue
    }

    consola.warn("Dropping unknown content part type", { unknownType: p.type })
  }
  return parts
}

function requireToolCallId(id: string | undefined, field: string): string {
  if (!id) throw badRequest(`${field} is missing`)
  return id
}

function translateMessages(
  messages: ChatCompletionsPayload["messages"],
): Array<ResponsesInput> {
  const input: Array<ResponsesInput> = []

  for (const msg of messages) {
    switch (msg.role) {
      case "system":
      case "developer": {
        input.push({
          type: "message",
          role: "developer",
          content: translateMessageContent(msg.content ?? ""),
        })

        break
      }
      case "user": {
        input.push({
          type: "message",
          role: "user",
          content: translateMessageContent(msg.content ?? ""),
        })

        break
      }
      case "assistant": {
        // TODO: When Copilot starts populating reasoning summaries,
        // we should detect thinking blocks in msg.content and map them
        // to { type: "reasoning", summary: [{type: "summary_text", text}] }
        // instead of sending them as plain assistant text. Currently
        // thinking blocks are concatenated into content by translateToOpenAI,
        // which works functionally but loses semantic meaning for /responses.
        if (msg.content) {
          input.push({
            type: "message",
            role: "assistant",
            content: translateMessageContent(msg.content),
          })
        }
        if (msg.tool_calls) {
          for (const tc of msg.tool_calls) {
            input.push({
              type: "function_call",
              name: tc.function.name,
              arguments: tc.function.arguments,
              call_id: requireToolCallId(tc.id, "assistant tool call id"),
            })
          }
        }

        break
      }
      case "tool": {
        input.push({
          type: "function_call_output",
          call_id: requireToolCallId(
            msg.tool_call_id,
            "tool message tool_call_id",
          ),
          output:
            typeof msg.content === "string" ?
              msg.content
            : JSON.stringify(msg.content),
        })

        break
      }
      // No default
    }
  }

  return input
}

function translateTools(
  payload: ChatCompletionsPayload,
): Partial<ResponsesPayload> {
  const result: Partial<ResponsesPayload> = {}

  if (payload.tools) {
    result.tools = payload.tools.map((t) => ({
      type: "function" as const,
      name: t.function.name,
      description: t.function.description,
      parameters: t.function.parameters,
    }))
  }

  if (payload.tool_choice) {
    result.tool_choice =
      typeof payload.tool_choice === "string" ?
        payload.tool_choice
      : { type: "function", name: payload.tool_choice.function.name }
  }

  return result
}

export function translateRequestToResponses(
  payload: ChatCompletionsPayload,
  effort?: string,
): ResponsesPayload {
  const result: ResponsesPayload = {
    model: payload.model,
    input: translateMessages(payload.messages),
    stream: payload.stream ?? undefined,
    ...translateTools(payload),
  }

  if (payload.max_tokens !== null && payload.max_tokens !== undefined)
    result.max_output_tokens = payload.max_tokens
  // Note: temperature and top_p are intentionally omitted — the /responses
  // API rejects them for GPT-5.x models ("Unsupported parameter").

  if (effort) result.reasoning = { effort }

  return result
}

// ── Response translation: Responses API → OpenAI Chat Completions ──

interface ResponsesResponse {
  id: string
  object: string
  created_at?: number
  model: string
  output: Array<ResponsesOutputItem>
  usage?: {
    input_tokens: number
    output_tokens: number
    total_tokens: number
  }
  status?: string
}

type ResponsesOutputItem =
  | {
      type: "message"
      role: "assistant"
      content: Array<ResponsesMessageContent>
    }
  | { type: "function_call"; name: string; arguments: string; call_id: string }
  | {
      type: "reasoning"
      id: string
      summary?: Array<{ type: "summary_text"; text: string }>
      encrypted_content?: string | null
    }

interface ResponsesMessageContent {
  type: "output_text"
  text: string
}

export function translateResponsesNonStreaming(
  resp: ResponsesResponse,
): ChatCompletionResponse {
  let textContent = ""
  let reasoningText = ""
  const toolCalls: Array<ToolCall> = []

  for (const item of resp.output) {
    switch (item.type) {
      case "message": {
        textContent += item.content.map((c) => c.text).join("")

        break
      }
      case "function_call": {
        toolCalls.push({
          id: item.call_id,
          type: "function",
          function: { name: item.name, arguments: item.arguments },
        })

        break
      }
      case "reasoning": {
        // Extract reasoning summary text if available
        if (item.summary && item.summary.length > 0) {
          reasoningText += item.summary.map((s) => s.text).join("\n")
        }

        break
      }
      // No default
    }
    // Skip other unknown item types
  }

  const finishReason = toolCalls.length > 0 ? "tool_calls" : "stop"

  return {
    id: resp.id,
    object: "chat.completion",
    created: resp.created_at ?? Math.floor(Date.now() / 1000),
    model: resp.model,
    choices: [
      {
        index: 0,
        message: {
          role: "assistant",
          content: textContent || null,
          ...(reasoningText ? { reasoning_text: reasoningText } : {}),
          ...(toolCalls.length > 0 ? { tool_calls: toolCalls } : {}),
        },
        logprobs: null,
        finish_reason: finishReason,
      },
    ],
    usage:
      resp.usage ?
        {
          prompt_tokens: resp.usage.input_tokens,
          completion_tokens: resp.usage.output_tokens,
          total_tokens: resp.usage.total_tokens,
        }
      : undefined,
  }
}

// ── Streaming translation: Responses API SSE → Chat Completions chunks ──

export interface ResponsesStreamState {
  responseId: string
  model: string
  toolCallIndex: number
  toolCallsByCallId: Partial<Record<string, ResponsesStreamToolCall>>
  toolCallsByOutputIndex: Partial<Record<number, ResponsesStreamToolCall>>
  fallbackId: string
  created: number
}

export function createResponsesStreamState(): ResponsesStreamState {
  return {
    responseId: "",
    model: "",
    toolCallIndex: 0,
    toolCallsByCallId: {},
    toolCallsByOutputIndex: {},
    fallbackId: `chatcmpl-${randomUUID()}`,
    created: Math.floor(Date.now() / 1000),
  }
}

interface ResponsesStreamToolCall {
  arguments: string
  callId: string
  index: number
  name: string
}

interface ResponsesStreamUsage {
  input_tokens: number
  output_tokens: number
  total_tokens: number
  input_tokens_details?: {
    cached_tokens: number
  }
}

interface ResponsesStreamResponse {
  id?: string
  model?: string
  usage?: ResponsesStreamUsage
  error?: {
    type?: string
    message?: string
  }
  incomplete_details?: {
    reason?: string
  }
}

interface ResponsesStreamItem {
  arguments?: string
  call_id?: string
  id?: string
  name?: string
  type?: string
}

interface ResponsesStreamEventData {
  arguments?: string
  call_id?: string
  code?: string
  delta?: string
  id?: string
  item?: ResponsesStreamItem
  message?: string
  model?: string
  name?: string
  output_index?: number
  response?: ResponsesStreamResponse
}

function makeChunk(
  streamState: ResponsesStreamState,
  {
    delta,
    finishReason,
    usage,
  }: {
    delta: Record<string, unknown>
    finishReason: string | null
    usage?: ChatCompletionChunk["usage"]
  },
): ChatCompletionChunk {
  return {
    id: streamState.responseId || streamState.fallbackId,
    object: "chat.completion.chunk",
    created: streamState.created,
    model: streamState.model,
    usage,
    choices: [
      {
        index: 0,
        delta: delta as ChatCompletionChunk["choices"][0]["delta"],
        finish_reason:
          finishReason as ChatCompletionChunk["choices"][0]["finish_reason"],
        logprobs: null,
      },
    ],
  }
}

function syncResponseMetadata(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
) {
  if (!streamState.responseId) {
    streamState.responseId = data.response?.id ?? data.id ?? ""
  }
  if (!streamState.model) {
    streamState.model = data.response?.model ?? data.model ?? ""
  }
}

function translateResponsesUsage(
  usage: ResponsesStreamUsage | undefined,
): ChatCompletionChunk["usage"] | undefined {
  if (!usage) {
    return undefined
  }

  return {
    prompt_tokens: usage.input_tokens,
    completion_tokens: usage.output_tokens,
    total_tokens: usage.total_tokens,
    ...(usage.input_tokens_details && {
      prompt_tokens_details: {
        cached_tokens: usage.input_tokens_details.cached_tokens,
      },
    }),
  }
}

function getToolCallDelta(
  toolCall: ResponsesStreamToolCall,
  argumentsChunk: string,
): ChatCompletionChunk["choices"][0]["delta"] {
  return {
    tool_calls: [
      {
        index: toolCall.index,
        function: { arguments: argumentsChunk },
      },
    ],
  }
}

function getNewToolCallDelta(
  toolCall: ResponsesStreamToolCall,
  argumentsChunk: string,
): ChatCompletionChunk["choices"][0]["delta"] {
  return {
    tool_calls: [
      {
        index: toolCall.index,
        id: toolCall.callId,
        type: "function",
        function: {
          name: toolCall.name,
          arguments: argumentsChunk,
        },
      },
    ],
  }
}

function getExistingToolCall(
  streamState: ResponsesStreamState,
  data: Pick<ResponsesStreamEventData, "call_id" | "output_index">,
): ResponsesStreamToolCall | undefined {
  if (data.output_index !== undefined) {
    const outputIndexToolCall =
      streamState.toolCallsByOutputIndex[data.output_index]
    if (outputIndexToolCall) {
      return outputIndexToolCall
    }
  }

  return data.call_id ? streamState.toolCallsByCallId[data.call_id] : undefined
}

function getOrCreateToolCall(
  streamState: ResponsesStreamState,
  {
    callId,
    initialArguments = "",
    name,
    outputIndex,
  }: {
    callId?: string
    initialArguments?: string
    name?: string
    outputIndex?: number
  },
): { isNew: boolean; toolCall: ResponsesStreamToolCall } | undefined {
  if (!callId || !name) {
    return undefined
  }

  const existingToolCall =
    streamState.toolCallsByCallId[callId]
    ?? (outputIndex !== undefined ?
      streamState.toolCallsByOutputIndex[outputIndex]
    : undefined)

  if (existingToolCall) {
    streamState.toolCallsByCallId[callId] = existingToolCall
    if (outputIndex !== undefined) {
      streamState.toolCallsByOutputIndex[outputIndex] = existingToolCall
    }

    return { isNew: false, toolCall: existingToolCall }
  }

  const toolCall: ResponsesStreamToolCall = {
    arguments: initialArguments,
    callId,
    index: streamState.toolCallIndex,
    name,
  }

  streamState.toolCallsByCallId[callId] = toolCall
  if (outputIndex !== undefined) {
    streamState.toolCallsByOutputIndex[outputIndex] = toolCall
  }
  streamState.toolCallIndex++

  return { isNew: true, toolCall }
}

function* syncToolArguments(
  streamState: ResponsesStreamState,
  toolCall: ResponsesStreamToolCall,
  nextArguments: string | undefined,
): Generator<ChatCompletionChunk> {
  if (!nextArguments || nextArguments === toolCall.arguments) {
    return
  }

  if (!nextArguments.startsWith(toolCall.arguments)) {
    consola.warn(
      "Tool call argument stream diverged; preserving streamed prefix",
      {
        callId: toolCall.callId,
        name: toolCall.name,
        accumulatedLength: toolCall.arguments.length,
        candidateLength: nextArguments.length,
        accumulatedTail: toolCall.arguments.slice(-80),
        candidateHead: nextArguments.slice(0, 80),
      },
    )
    return
  }

  const missingArguments = nextArguments.slice(toolCall.arguments.length)
  toolCall.arguments = nextArguments

  if (!missingArguments) {
    return
  }

  yield makeChunk(streamState, {
    delta: getToolCallDelta(toolCall, missingArguments),
    finishReason: null,
  })
}

function* handleCreatedEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  syncResponseMetadata(streamState, data)
  yield makeChunk(streamState, {
    delta: { role: "assistant", content: "" },
    finishReason: null,
  })
}

function* handleOutputTextDeltaEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  if (!data.delta) {
    return
  }

  yield makeChunk(streamState, {
    delta: { content: data.delta },
    finishReason: null,
  })
}

function* handleOutputItemAddedEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  if (data.item?.type !== "function_call") {
    return
  }

  const toolCall = getOrCreateToolCall(streamState, {
    callId: data.item.call_id,
    initialArguments: data.item.arguments ?? "",
    name: data.item.name,
    outputIndex: data.output_index,
  })

  if (!toolCall?.isNew) {
    return
  }

  yield makeChunk(streamState, {
    delta: getNewToolCallDelta(toolCall.toolCall, data.item.arguments ?? ""),
    finishReason: null,
  })
}

function* handleFunctionCallArgumentsDeltaEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  if (!data.delta) {
    return
  }

  const existingToolCall = getExistingToolCall(streamState, data)
  if (existingToolCall) {
    existingToolCall.arguments += data.delta
    yield makeChunk(streamState, {
      delta: getToolCallDelta(existingToolCall, data.delta),
      finishReason: null,
    })
    return
  }

  const toolCall = getOrCreateToolCall(streamState, {
    callId: data.call_id,
    initialArguments: data.delta,
    name: data.name,
    outputIndex: data.output_index,
  })

  if (!toolCall) {
    return
  }

  yield makeChunk(streamState, {
    delta: getNewToolCallDelta(toolCall.toolCall, data.delta),
    finishReason: null,
  })
}

function* handleFunctionCallArgumentsDoneEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  const existingToolCall = getExistingToolCall(streamState, data)
  if (!existingToolCall) {
    return
  }

  yield* syncToolArguments(streamState, existingToolCall, data.arguments)
}

function getExistingOrCreateCompletedToolCall(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): { isNew: boolean; toolCall: ResponsesStreamToolCall } | undefined {
  const existingToolCall = getExistingToolCall(streamState, {
    call_id: data.item?.call_id,
    output_index: data.output_index,
  })

  if (existingToolCall) {
    return { isNew: false, toolCall: existingToolCall }
  }

  return getOrCreateToolCall(streamState, {
    callId: data.item?.call_id,
    initialArguments: data.item?.arguments ?? "",
    name: data.item?.name,
    outputIndex: data.output_index,
  })
}

function* handleOutputItemDoneEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  if (data.item?.type !== "function_call") {
    return
  }

  const toolCall = getExistingOrCreateCompletedToolCall(streamState, data)
  if (!toolCall) {
    return
  }

  if (toolCall.isNew) {
    yield makeChunk(streamState, {
      delta: getNewToolCallDelta(toolCall.toolCall, data.item.arguments ?? ""),
      finishReason: null,
    })
  }

  yield* syncToolArguments(streamState, toolCall.toolCall, data.item.arguments)
}

function* handleCompletedEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  syncResponseMetadata(streamState, data)
  const hasToolCalls = Object.keys(streamState.toolCallsByCallId).length > 0

  yield makeChunk(streamState, {
    delta: {},
    finishReason: hasToolCalls ? "tool_calls" : "stop",
    usage: translateResponsesUsage(data.response?.usage),
  })
}

function mapIncompleteReasonToFinishReason(
  reason: string | undefined,
): "stop" | "length" | "content_filter" {
  switch (reason) {
    case "max_output_tokens": {
      return "length"
    }
    case "content_filter": {
      return "content_filter"
    }
    default: {
      return "stop"
    }
  }
}

function* handleFailedEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  syncResponseMetadata(streamState, data)
  const errorType = data.response?.error?.type ?? "api_error"
  const message = data.response?.error?.message ?? "Upstream response failed"
  consola.warn("Upstream /responses failed", { type: errorType, message })

  const chunk = makeChunk(streamState, {
    delta: {},
    finishReason: null,
    usage: translateResponsesUsage(data.response?.usage),
  })
  chunk.error = { type: errorType, message }
  yield chunk
}

function* handleErrorEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  const errorType = data.code ?? "api_error"
  const message = data.message ?? "Upstream error"
  consola.warn("Upstream /responses error event", {
    type: errorType,
    message,
  })

  const chunk = makeChunk(streamState, {
    delta: {},
    finishReason: null,
  })
  chunk.error = { type: errorType, message, code: data.code }
  yield chunk
}

function* handleIncompleteEvent(
  streamState: ResponsesStreamState,
  data: ResponsesStreamEventData,
): Generator<ChatCompletionChunk> {
  syncResponseMetadata(streamState, data)
  const finishReason = mapIncompleteReasonToFinishReason(
    data.response?.incomplete_details?.reason,
  )

  yield makeChunk(streamState, {
    delta: {},
    finishReason,
    usage: translateResponsesUsage(data.response?.usage),
  })
}

export function* translateResponsesStreamEvent(
  event: {
    event: string
    data: ResponsesStreamEventData
  },
  streamState: ResponsesStreamState,
): Generator<ChatCompletionChunk> {
  const { event: eventType, data } = event

  switch (eventType) {
    case "response.created": {
      yield* handleCreatedEvent(streamState, data)
      break
    }

    case "response.in_progress": {
      syncResponseMetadata(streamState, data)
      break
    }

    case "response.output_text.delta": {
      yield* handleOutputTextDeltaEvent(streamState, data)
      break
    }

    case "response.output_item.added": {
      yield* handleOutputItemAddedEvent(streamState, data)
      break
    }

    case "response.function_call_arguments.delta": {
      yield* handleFunctionCallArgumentsDeltaEvent(streamState, data)
      break
    }

    case "response.function_call_arguments.done": {
      yield* handleFunctionCallArgumentsDoneEvent(streamState, data)
      break
    }

    case "response.output_item.done": {
      yield* handleOutputItemDoneEvent(streamState, data)
      break
    }

    case "response.completed": {
      yield* handleCompletedEvent(streamState, data)
      break
    }

    case "response.failed": {
      yield* handleFailedEvent(streamState, data)
      break
    }

    case "response.incomplete": {
      yield* handleIncompleteEvent(streamState, data)
      break
    }

    case "error": {
      yield* handleErrorEvent(streamState, data)
      break
    }

    default: {
      break
    }
  }
}

// ── Service function: call the upstream /responses endpoint ──

export async function createResponses(
  payload: ChatCompletionsPayload,
  effort?: string,
  signal?: AbortSignal,
) {
  if (!state.copilotToken) throw new Error("Copilot token not found")

  const responsesPayload = translateRequestToResponses(payload, effort)

  const url = `${copilotBaseUrl(state)}/responses`
  consola.debug(`Sending /responses request for model: ${payload.model}`)

  const response = await copilotFetch(url, {
    method: "POST",
    body: JSON.stringify(responsesPayload),
    signal,
  })

  if (!response.ok) {
    consola.error("Failed to create responses", response)
    throw new HTTPError("Failed to create responses", response)
  }

  if (payload.stream) {
    return events(response)
  }

  const rawResponse = (await response.json()) as ResponsesResponse
  return translateResponsesNonStreaming(rawResponse)
}

import consola from "consola"
import { events } from "fetch-event-stream"

import type { EffortLevel } from "~/lib/effort"
import type { AnthropicMessagesPayload } from "~/routes/messages/anthropic-types"

import { copilotBaseUrl } from "~/lib/api-config"
import { copilotFetch } from "~/lib/copilot-fetch"
import { resolveEffort as resolveCatalogEffort } from "~/lib/effort"
import { HTTPError } from "~/lib/error"
import {
  anthropicToCopilotModelId,
  extractEffortFromModelName,
} from "~/lib/model-mapping"
import { state } from "~/lib/state"

/**
 * Detect Claude model generation from the copilot model ID.
 *
 * Thinking type support varies by generation:
 *   Older (haiku-4.5, sonnet-4/4.5, opus-4.5): disabled, enabled
 *   4.6   (sonnet-4.6, opus-4.6[-1m]):          disabled, enabled, adaptive
 *   4.7+  (opus-4.7[-1m-internal]):              disabled, adaptive (rejects enabled)
 *
 * Future models default to adaptive (the trend is clear).
 */
type ModelGeneration = "older" | "4.6" | "4.7+"

/** Models that only accept enabled (not adaptive) */
const OLDER_MODELS = ["haiku-4.5", "sonnet-4.5", "sonnet-4", "opus-4.5"]

function detectGeneration(copilotModelId: string): ModelGeneration {
  // Check older models first (allowlist approach)
  if (OLDER_MODELS.some((m) => copilotModelId.includes(m))) return "older"
  if (copilotModelId.includes("4.6")) return "4.6"
  // 4.7 and all future models default to adaptive
  return "4.7+"
}

/**
 * Compute a thinking budget from effort level and max_tokens.
 */
function budgetFromEffort(
  effort: EffortLevel | undefined,
  maxTokens: number,
  existingBudget: number | undefined,
): number {
  let budget: number
  switch (effort) {
    case "low": {
      return 0
    } // caller handles this as disabled
    case "medium": {
      budget = existingBudget ?? Math.max(1024, Math.floor(maxTokens * 0.5))
      break
    }
    case "high": {
      budget = existingBudget ?? Math.max(1024, Math.floor(maxTokens * 0.8))
      break
    }
    case "max": {
      budget = Math.max(1024, maxTokens - 1)
      break
    }
    default: {
      budget = existingBudget ?? Math.max(1024, maxTokens - 1)
    }
  }
  // budget_tokens must be strictly less than max_tokens
  return Math.min(budget, maxTokens - 1)
}

interface NormalizeThinkingOpts {
  thinking: AnthropicMessagesPayload["thinking"]
  maxTokens: number
  generation: ModelGeneration
  effort?: EffortLevel
}

/**
 * Normalize thinking config for the upstream Copilot /v1/messages endpoint.
 *
 * Applies per-generation rules:
 *   - Older models: downgrade adaptive → enabled (they reject adaptive)
 *   - 4.6 models: pass through as-is (they accept everything)
 *   - 4.7 models: upgrade enabled → adaptive (they reject enabled)
 *
 * Also maps output_config.effort to budget_tokens.
 */
function normalizeThinking(
  opts: NormalizeThinkingOpts,
): Record<string, unknown> | undefined {
  const { thinking, maxTokens, generation, effort } = opts
  // Low effort: disable thinking entirely regardless of generation
  if (effort === "low") {
    return { type: "disabled" }
  }

  // If no thinking config and no effort signal, nothing to do
  if (!thinking && !effort) return undefined

  const requestedType = thinking?.type ?? "enabled"

  // Disabled is universally supported
  if (requestedType === "disabled") return thinking

  const budgetTokens = budgetFromEffort(
    effort,
    maxTokens,
    thinking?.budget_tokens,
  )

  switch (generation) {
    case "4.6": {
      // 4.6 accepts everything — pass through type as-is
      // adaptive does NOT accept budget_tokens, only enabled does
      if (requestedType === "adaptive") {
        return { type: "adaptive" }
      }
      return { type: "enabled", budget_tokens: budgetTokens }
    }

    case "4.7+": {
      // 4.7+ rejects 'enabled' — must use adaptive (no budget_tokens)
      return { type: "adaptive" }
    }

    default: {
      // Older models reject 'adaptive' — must use enabled
      return { type: "enabled", budget_tokens: budgetTokens }
    }
  }
}

/** Whitelist of optional fields safe to forward to Copilot /v1/messages */
const OPTIONAL_FIELDS = [
  "system",
  "metadata",
  "stop_sequences",
  "temperature",
  "top_p",
  "top_k",
  "tools",
  "tool_choice",
  "service_tier",
] as const

/**
 * Check whether a model supports output_config.effort by looking at
 * the advertised reasoning_effort capabilities from the model catalog.
 */
function supportsEffort(copilotModelId: string): boolean {
  const model = state.models?.data.find((m) => m.id === copilotModelId) as
    | { capabilities?: { supports?: { reasoning_effort?: Array<string> } } }
    | undefined
  return Boolean(model?.capabilities?.supports?.reasoning_effort?.length)
}

interface ResolveEffortOpts {
  copilotModelId: string
  effort: string | undefined
  body: Record<string, unknown>
  outputConfig: Record<string, unknown> | undefined
}

/**
 * Resolve effort by forwarding output_config.effort directly.
 * The upstream API validates supported values per model.
 * Returns whether effort was handled.
 */
function resolveEffort(opts: ResolveEffortOpts): boolean {
  const { copilotModelId, effort, body, outputConfig } = opts
  if (!effort) return false

  if (supportsEffort(copilotModelId)) {
    const resolved = resolveCatalogEffort({
      modelId: copilotModelId,
      requested: effort,
      cachedModels: state.models,
    })
    if (resolved) body.output_config = { ...outputConfig, effort: resolved }
    return true
  }

  return false
}

/**
 * Build a sanitized request body for the upstream Copilot /v1/messages endpoint.
 * Only forward fields that the Copilot API accepts — strip extras like
 * output_config that Claude Code sends but Copilot doesn't support.
 */
export function buildNativeBody(
  payload: AnthropicMessagesPayload,
  overrides: Record<string, unknown>,
  is1M?: boolean,
): Record<string, unknown> {
  const copilotModelId = anthropicToCopilotModelId(
    payload.model,
    is1M ?? state.is1MContext,
  )

  const body: Record<string, unknown> = {
    model: copilotModelId,
    messages: payload.messages,
    max_tokens: payload.max_tokens,
  }

  for (const field of OPTIONAL_FIELDS) {
    if (payload[field] !== undefined) {
      body[field] = payload[field]
    }
  }

  // Sanitize stop_sequences: Copilot rejects whitespace-only entries (e.g. "\n" from Buddy)
  if (body.stop_sequences) {
    const filtered = (body.stop_sequences as Array<string>).filter((s) =>
      s.trim(),
    )
    if (filtered.length > 0) {
      body.stop_sequences = filtered
    } else {
      delete body.stop_sequences
    }
  }

  // Extract effort: prefer output_config.effort, fall back to legacy model-name suffix
  const { effort: modelNameEffort } = extractEffortFromModelName(payload.model)
  const requestedEffort = payload.output_config?.effort ?? modelNameEffort
  const effort = requestedEffort === "auto" ? undefined : requestedEffort
  const generation = detectGeneration(copilotModelId)

  const effortHandled = resolveEffort({
    copilotModelId,
    effort,
    body,
    outputConfig: payload.output_config,
  })

  const thinking = normalizeThinking({
    thinking: payload.thinking,
    maxTokens: payload.max_tokens,
    generation,
    effort: effortHandled ? undefined : effort,
  })
  if (thinking) body.thinking = thinking

  Object.assign(body, overrides)

  return body
}

/**
 * Forward a /v1/messages request directly to the upstream Copilot API's
 * native Anthropic /v1/messages endpoint, with only supported fields.
 */
// eslint-disable-next-line max-params
export async function forwardNativeMessages(
  payload: AnthropicMessagesPayload,
  streamOverride?: boolean,
  is1M?: boolean,
  signal?: AbortSignal,
): Promise<Response> {
  const overrides: Record<string, unknown> = {}
  if (streamOverride !== undefined) overrides.stream = streamOverride

  const body = buildNativeBody(payload, overrides, is1M)

  const url = `${copilotBaseUrl(state)}/v1/messages`

  consola.debug(
    `Native passthrough: ${payload.model} -> ${body.model as string} via ${url}`,
  )

  const response = await copilotFetch(url, {
    method: "POST",
    body: JSON.stringify(body),
    signal,
  })

  if (!response.ok) {
    throw new HTTPError(
      `Native /v1/messages request failed for model ${body.model as string}`,
      response,
    )
  }

  return response
}

/**
 * Forward a native /v1/messages request and return the parsed JSON response.
 */
export async function forwardNativeMessagesNonStreaming(
  payload: AnthropicMessagesPayload,
  is1M?: boolean,
  signal?: AbortSignal,
) {
  const response = await forwardNativeMessages(payload, false, is1M, signal)
  return await response.json()
}

/**
 * Forward a native /v1/messages request in streaming mode and yield SSE events.
 */
export async function* forwardNativeMessagesStreaming(
  payload: AnthropicMessagesPayload,
  is1M?: boolean,
  signal?: AbortSignal,
) {
  const response = await forwardNativeMessages(payload, true, is1M, signal)

  const stream = events(response)
  for await (const event of stream) {
    if (!event.data || event.data === "[DONE]") continue
    try {
      const data = JSON.parse(event.data) as Record<string, unknown>
      yield { type: (event.event ?? data.type) as string, data }
    } catch {
      consola.warn("Failed to parse native stream event:", event.data)
    }
  }
}

